#include <vector>

/**
 * @brief 通过下滤操作，将堆中某节点向下调整，保持堆的性质。
 * @param heap      堆数组
 * @param index     当前节点索引
 * @param size      堆的有效大小（即当前堆的大小）
 */
static void sift_down(std::vector<int>& heap, int index, int size) {
    while (true) {
        int left = 2 * index + 1;     // 左子节点索引
        int right = 2 * index + 2;    // 右子节点索引
        int largest = index;          // 初始认为当前节点是最大的

        // 比较左子节点是否更大
        if (left < size && heap[left] > heap[largest]) {
            largest = left;
        }

        // 比较右子节点是否更大
        if (right < size && heap[right] > heap[largest]) {
            largest = right;
        }

        // 如果最大值是当前节点，说明已经是最小堆的结构，结束
        if (largest == index) {
            break;
        }

        // 交换当前节点与最大值节点
        std::swap(heap[index], heap[largest]);
        index = largest;  // 继续下滤
    }
}

/**
