    for (int end = total - 1; end > 0; --end) {
        // 交换堆顶和当前末尾元素
        std::swap(result[0], result[end]);

        // 重新调整堆，使堆保持最大堆性质
        sift_down(result, 0, end);
    }

    return result;
}
